def clamp_literal(v):
 carry=v<100;al=(v-100)&255;cl=255 if carry else 0
 return ((al&cl)+100)&255
for v in range(256):assert clamp_literal(v)==min(v,100)
toggle_cases=0
for count in range(256):
 for flag in range(256):
  f=flag;clear=False
  if count:f^=1;clear=f==0
  assert (f,clear)==(flag^int(count!=0),bool(count and flag==1))
  for selector in [0x13,0x14]:
   assert selector in [0x13,0x14];toggle_cases+=1
composed_cases=0
for mask in [7,15]:
 for count in range(256):
  for tick in range(256):
   for active in [0,1]:
    n=(count-1)&255 if active and not tick&mask else count
    expired=bool(active and n==0);newflag=0 if expired else active
    ui_called=n!=count;final=clamp_literal(n) if ui_called else n
    expected=min((count-1)%256,100) if active and tick%(mask+1)==0 else count
    assert final==expected
    composed_cases+=1
def overlay_sequence(word,flagmap,flagobj,mapcount,objcount):
 signed=word if word<32768 else word-65536
